1181	  /**
1182	   * The accomplishments of this tick (§2's results), read from the ledger, which alone moves rubbings and gold: each
1183	   * rubbing that changed hands since the last tick (from a source: collected; from a cache: a cache claimed; from one
1184	   * player to another: a theft and a loss; from a player into a cache: a loss), each balance that changed, and each
1185	   * island a player first moors at.
1186	   */
1187	  private reportAccomplishments(_tick: number): void {
1188	    // Unknown ids are dropped with every other report's, before the flow's step (`knownFlowReports`).
1189	    const report = (entry: FlowReport) => this.flowReports.push(entry);
1190	    for (const rubbing of this.ledger.rubbings) {
1191	      const before = this.lastLocations.get(rubbing.id);
1192	      this.lastLocations.set(rubbing.id, rubbing.location);
1193	      // The first tick in play only records where each rubbing is.
1194	      if (before === undefined) continue;
1195	      const from = holderOf(before);
1196	      const to = holderOf(rubbing.location);
1197	      if (from === to) continue;
1198	      if (from === undefined && to !== undefined) {
1199	        if (before.kind === "source") report({ kind: "collected", playerId: to });
1200	        else if (before.kind === "cache") report({ kind: "cache-claimed", playerId: to });
1201	      } else if (from !== undefined && to !== undefined) {
1202	        report({ kind: "stole", playerId: to });
1203	        report({ kind: "lost", playerId: from });
1204	      } else if (from !== undefined) {
1205	        report({ kind: "lost", playerId: from });
1206	      }
1207	    }
1208	    for (const player of this.ledger.players) {
1209	      if (this.reportedGold.get(player.id) === player.gold) continue;
1210	      this.reportedGold.set(player.id, player.gold);
1211	      report({ kind: "gold", playerId: player.id, gold: player.gold });
1212	    }
1213	    for (const ship of this.simulation.ships) {
1214	      const island = ship.dock === NOT_DOCKED ? -1 : (this.config.map.docks[ship.dock]?.island ?? -1);
1215	      if (island < 0 || this.visited.has(`${ship.id}:${island}`)) continue;
1216	      this.visited.add(`${ship.id}:${island}`);
1217	      report({ kind: "island-visited", playerId: ship.id, island: String(island) });
1218	    }
1219	  }
1220	
1221	  /**
1222	   * §2's match flow, one world tick: the joins, leaves and start requests since the last tick, this tick's
1223	   * accomplishments and the claim's end, in that order. Reports naming a player the flow does not know are dropped
1224	   * first (`knownFlowReports`: the match module throws on them), and counted for tests.
1225	   */
1226	  private stepFlow(tick: number, claimEnd?: FlowReport): void {
1227	    const reports = this.flowReports;
1228	    this.flowReports = [];
1229	    if (claimEnd !== undefined) reports.push(claimEnd);
1230	    this.stepFlowWith(tick, reports);
1231	  }
1232	
1233	  private stepFlowWith(tick: number, reports: readonly FlowReport[]): void {
1234	    const known = knownFlowReports(this.flow.players, reports);
1235	    this.droppedReports.push(...known.dropped);
1236	    const stepped = stepMatch(this.flowConfig, this.flow, { tick, reports: known.reports });
1237	    this.flow = stepped.state;
1238	    for (const event of stepped.events) this.applyFlowEvent(event);
1239	  }
1240	
1241	  private applyFlowEvent(event: FlowEvent): void {
1242	    switch (event.kind) {
1243	      case "start-refused":
1244	        this.clients.get(event.playerId)?.send(MatchMessageType.StartRefused, { reason: event.reason } satisfies StartRefusedMessage);
1245	        return;
1246	      // No `join-refused`: the room reports a join only in the lobby (onJoin refuses one after it), before any start
1247	      // in the same step, and seats no more players than the flow has seats (docs/match-online-coverage.md).
1248	      case "phase-changed":
1249	        // §2: once the ready countdown starts, admission refuses late arrivals; back in the lobby, it admits again.
1250	        if (event.to === "ready" || event.to === "lobby") void this.setMatchmaking({ metadata: { code: this.state.code, custom: privateMatch.custom, started: event.to === "ready" } });
1251	        return;
1252	      case "control-started":
1253	        this.startControl(event.tick);
1254	        return;
1255	      case "match-ended":
1256	        this.endMatch(event.results);
1257	        return;
1258	      default:
1259	        return;
1260	    }
1261	  }
1262	
1263	  /**
1264	   * §2's control start: every ship present gets the encounter rules' departure protection from this tick, the claim
1265	   * config's deadline counts from it (the timer's end), and the reveals' clocks start. The accomplishments start from
1266	   * the first tick in play, which records where each rubbing is and each balance (the starting gold).
1267	   */
1268	  private startControl(tick: number): void {
1269	    // Every ship's player is in the match (the room's invariant): a leave removes the ship at once.
1270	    const ids = this.simulation.ships.map((ship) => ship.id);
1271	    this.encounters = createEncounterState(this.encounterConfig, { tick, spawnProtected: ids });
1272	    this.claimConfig = claimConfigFor(this.tuning, this.finalIsland.claimPoint, tick, this.config.map);
1273	    this.claim = createClaimState(this.claimConfig, tick);
1274	    this.intelConfig = intelConfigFor(this.tuning, this.finalIsland.claimPoint, tick, this.config.map);
1275	    this.intel = createIntelState(this.intelConfig, this.seedOf("intel"), tick - 1);
1276	  }
1277	
1278	  /**
1279	   * The match is over (§2, §5): outcomes freeze. A duel still running ends without theft (§2), each fighter's lobby
1280	   * showing the cancellation for a moment; the ships stop taking input; the results are the flow's, recorded once.
1281	   */
1282	  private endMatch(results: MatchResults): void {
1283	    const tick = results.tick;
1284	    for (const duel of this.seaDuels.values()) {
1285	      if (findDuel(this.ledger, duel.id)?.phase === "fighting" && tick >= this.ledger.tick) {
1286	        this.ledgerStep("reportDuelResult", reportDuelResult(this.ledger, { duelId: duel.id, tick, outcome: "cancelled" }));
1287	      }
1288	      if (duel.machine.outcome === undefined) duel.machine.end(null, "cancelled");
1289	      duel.ended = true;
1290	      duel.endedByRules = true;
1291	      duel.removeAfterTick ??= tick + DUEL_RESULT_TICKS;
1292	      this.state.markers.delete(duel.key);
1293	    }
1294	    recordOutcome({ code: this.state.code, results });
1295	    console.log(`match ${this.state.code} ended at tick ${tick}: ${results.reason}${results.winner === null ? ", no winner" : `, won by ${results.winner}`}`);
1296	  }
1297	
1298	  /**
1299	   * §2 and §5's reveals, one world tick after the flow: the intel module reads the ledger's rubbings and the ships,
1300	   * and the room delivers only its reveal messages, each to exactly its recipients (§16): the final island's sector to
1301	   * everyone, its exact claim point only to a full-set holder. Rumors and the journal come with `intel-online`.
1302	   */
1303	  private stepReveals(tick: number): void {
1304	    if (this.intelConfig === undefined || this.intel === undefined) return;
1305	    const stepped = stepIntel(this.intelConfig, this.intel, this.intelView(tick));
1306	    this.intel = stepped.state;
1307	    for (const { to, body } of stepped.messages) {
1308	      const reveal = revealOf(body);
1309	      if (reveal === undefined) continue;
1310	      if (reveal.kind === "final-sector") {
1311	        this.state.finalSector = reveal.name;
1312	        this.state.finalSectorIndex = reveal.sector;
1313	      }
1314	      const recipients = revealRecipients(to, [...this.clients].map((client) => client.sessionId));
1315	      for (const id of recipients) {
1316	        if (reveal.kind === "final-route") this.routes.set(id, { active: true, x: reveal.x, y: reveal.y });
1317	        if (reveal.kind === "final-route-inactive") {
1318	          const route = this.routes.get(id);
1319	          if (route !== undefined) route.active = false;
1320	        }
1321	        this.clients.get(id)?.send(MatchMessageType.Reveal, reveal);
1322	      }
1323	    }
1324	  }
1325	
1326	  /**
1327	   * The world as the intel module reads it: every player in the match at their ship, and every rubbing where the
1328	   * ledger has it. A player who left while a duel still reserves their rubbings stays in the view, at the position
1329	   * they left from, until that duel settles.
1330	   */
1331	  private intelView(tick: number): IntelWorldView {
1332	    const ships = new Map(this.simulation.ships.map((ship) => [ship.id, ship]));
1333	    const holding = new Set(this.ledger.rubbings.flatMap((rubbing) => (rubbing.location.kind === "duel" ? [rubbing.location.playerId] : [])));
1334	    const players = this.ledger.players.flatMap((player) => {
1335	      const ship = ships.get(player.id);
1336	      if (player.status !== "left" && ship !== undefined) return [{ id: player.id, x: ship.x, y: ship.y }];
1337	      if (holding.has(player.id)) return [{ id: player.id, x: player.exit?.x ?? 0, y: player.exit?.y ?? 0 }];
1338	      return [];
1339	    });
1340	    const rubbings: IntelRubbing[] = this.ledger.rubbings.map((rubbing) => {
1341	      const location = rubbing.location;
1342	      switch (location.kind) {
1343	        case "source": {
1344	          const source = this.ledger.sources.find((each) => each.id === location.sourceId)!;
1345	          return { id: rubbing.id, type: rubbing.type, place: { kind: "source", island: source.island, x: source.x, y: source.y } };
1346	        }
1347	        case "cache": {
1348	          const cache = this.ledger.caches.find((each) => each.id === location.cacheId)!;
1349	          return { id: rubbing.id, type: rubbing.type, place: { kind: "cache", x: cache.x, y: cache.y } };
1350	        }
1351	        case "player":
1352	          return { id: rubbing.id, type: rubbing.type, place: { kind: "carried", playerId: location.playerId } };
1353	        case "duel":
1354	          return { id: rubbing.id, type: rubbing.type, place: { kind: "duel", playerId: location.playerId } };
1355	      }
1356	    });
1357	    return { tick, players, rubbings };
1358	  }
1359	
1360	  /** §12's server fault: a world tick threw. The match is aborted with no winner and no competitive penalty. */
1361	  private fault(tick: number, error: unknown): void {
1362	    console.error(`match ${this.state.code} fault at world tick ${tick} (aborting):`, error);
1363	    if (this.flow.end !== null) return;
1364	    this.flowReports = [];
1365	    this.stepFlowWith(Math.max(tick, this.flow.tick + 1), [{ kind: "fault" }]);
1366	  }
1367	
1368	  /** The private host's start request (§2): rate-capped and validated, then judged by the flow on the next tick. */
1369	  private receiveStart(sessionId: string, message: unknown): void {
1370	    const frame = this.simulation.frame;
1371	    const rate = this.startRate.get(sessionId) ?? { windowStart: frame, count: 0 };
1372	    if (frame - rate.windowStart >= STEPS_PER_SECOND) {
1373	      rate.windowStart = frame;
1374	      rate.count = 0;
1375	    }
1376	    rate.count++;
1377	    this.startRate.set(sessionId, rate);
1378	    if (rate.count > MAX_START_MATCH_PER_SECOND) return;
1379	    if (validateStartMatchMessage(message) === undefined) return;
1380	    // Only a seated player sends messages (onJoin adds them to the ledger and the flow's reports first).
1381	    this.flowReports.push({ kind: "start", playerId: sessionId });
1382	  }
1383	
1384	  /** Every player gone: a match that left its lobby ends abandoned (§12), stepped once more before the room closes. */
1385	  override onDispose(): void {
1386	    if (this.flow.end !== null || this.flowReports.length === 0) return;
1387	    const tick = Math.max(this.simulation.worldTick + 1, this.flow.tick + 1);
1388	    // The leavers' rubbings went into caches since the last tick: those losses count before the end.
1389	    if (this.inPlay()) this.reportAccomplishments(tick);
1390	    const reports = this.flowReports;
1391	    this.flowReports = [];
1392	    this.stepFlowWith(tick, reports);
1393	  }
1394	
1395	  /** A player's seat: their join order in the flow, from 1 (0 before the flow has seen them join). */
1396	  seatOf(id: string): number {
1397	    const player = this.flow.players.find((each) => each.id === id);
1398	    return player === undefined ? 0 : player.order + 1;
1399	  }
1400	
1401	  /** A system's seed, derived from the match's master secret (`deriveSeed`). */
1402	  private seedOf(system: SeedSystem): number {
1403	    return deriveSeed(this.secret, system);
1404	  }
1405	
1406	  private requireTestHooks(): void {
1407	    if (!this.tuning.testHooks) throw new Error("the room's test hooks are off (MatchTuning.testHooks)");
1408	  }
1409	
1410	  /** Test-only (`testHooks`): the next world tick throws inside the room, as a server fault would (§12: aborted). */
1411	  injectFault(): void {
1412	    this.requireTestHooks();
1413	    this.faultNext = true;
1414	  }
1415	
1416	  /**
1417	   * Test-only (`testHooks`): the room's clock stops right after world tick `tick` (patches still go out, messages are
1418	   * still received) until `resumeWorld`, so a test can line an input up with an exact tick.
1419	   */
1420	  pauseAfterTick(tick: number): void {
1421	    this.requireTestHooks();
1422	    this.pauseAt = tick;
1423	  }
1424	
1425	  resumeWorld(): void {
1426	    this.requireTestHooks();
1427	    this.paused = false;
1428	  }
1429	
1430	  /**
1431	   * Test-only (`testHooks`): reports for the flow's next step, as if the room had made them, so a test can show what
1432	   * the room does with a report naming a player the flow does not know.
1433	   */
1434	  injectFlowReports(reports: readonly FlowReport[]): void {
1435	    this.requireTestHooks();
1436	    this.flowReports.push(...reports);
1437	  }
