  readonly sourceLayout: readonly (readonly string[])[] | undefined;
  /**
   * The match's one private master secret (§3, §16), from which every system's seed is derived (`deriveSeed`):
   * production draws it from `node:crypto` (`drawMasterSecret`); tests inject their own to show what follows it.
   */
  readonly masterSecret: () => Uint8Array;
  /** Test-only: the final-socket secret instead of the one derived from the master secret, so a test knows the island. */
  readonly finalSocketSecret: number | undefined;
  /** Test-only: islands whose sources are open from the start, or whose ruin has a pinned kind (`TEST_RUINS_ENV`). */
  readonly testRuins: TestRuins | undefined;
  /** Test-only: the kit on each island's pedestal, in island order, instead of the fruit seed's deal (`TEST_FRUITS_ENV`). */
  readonly testFruits: TestFruits | undefined;
  /** Test-only: the room's `injectFault` and `pauseAfterTick` hooks work (off by default; they throw otherwise). */
  readonly testHooks: boolean;
  /** Check `checkLedger` and the room's own invariant after every world tick (development and tests). */
  readonly checkInvariants: boolean;
}

export const DEFAULT_MATCH_TUNING: MatchTuning = {
  objectives: objectiveRules,
  encounters: encounterRules,
  duelAbsenceTicks: DUEL_RECONNECT_SECONDS * WORLD_TICKS_PER_SECOND,
  reconnectionSeconds: RECONNECTION_OUTER_BOUND_SECONDS,
  match: defaultMatchRules,
  claim: defaultClaimRules,
  intel: defaultIntelRules,
  sourceLayout: undefined,
  masterSecret: drawMasterSecret,
  finalSocketSecret: undefined,
  testRuins: undefined,
  testFruits: undefined,
  testHooks: false,
  checkInvariants: true,
};

export { recordedOutcomes, type MatchOutcome } from "./outcomes.js";

/** A duel at sea: the encounter rules' duel, its synced lobby and marker, and the duel machine the fighters play. */
interface SeaDuel {
  /** The encounter rules' duel id, also the ledger's. */
  readonly id: string;
  /** The opaque key of its lobby and marker in the synced state. */
  readonly key: string;
  /** Attacker (slot 0), then the grappled player (slot 1). */
  readonly players: readonly [string, string];
  readonly lobby: SeaDuelSchema;
  readonly machine: DuelMachine;
  /** The rules' ready check ended it (a forfeit or a cancellation), so no end report goes back to them. */
  endedByRules: boolean;
  /** The fight's end went to the rules (or they decided it themselves). */
  ended: boolean;
  /** The ledger's settlement went to the rules. */
  settled: boolean;
  /** The world tick after which the lobby leaves the fighters' views, once settled. */
  removeAfterTick: number | undefined;
}

/** A player whose connection dropped (§12): their seat's outer bound, and since when they are away from a duel. */
interface Away {
  readonly reconnection: Deferred<Client> | undefined;
  /** The world tick they dropped out of an unfinished duel; undefined outside one. */
  duelAbsentSince: number | undefined;
}

/** What a player last saw of their own holds and duels, for their HUD. */
interface Notices {
  channelResult: string;
  channelResultAt: number;
  settledRole: string;
  stolen: string;
  goldChange: number;
  settledAt: number;
  settledChoice: string;
  choiceDeadline: number;
  /** §5: why this player's last claim channel reset, and on which world tick. */
  claimInterrupt: string;
  claimInterruptAt: number;
  /** §9: how this player's last attempt to eat a fruit ended ("eaten:<kit>", "interrupted:<reason>", "refused:<reason>"), and when. */
  fruitResult: string;
  fruitResultAt: number;
}

/** A player's final-island route (§5), as the reveals gave it: known once, inactive while the set is broken. */
interface Route {
  active: boolean;
  readonly x: number;
  readonly y: number;
}

/** What tests and diagnostics read about a duel at sea. */
export interface SeaDuelDiagnostics extends DuelDiagnostics {
  readonly id: string;
  readonly outcome: DuelOutcome | undefined;
  readonly players: readonly [string, string];
  readonly seed: number;
  /** Both fighters' kits in the duel's state (§9), fixed from its frame 0. */
  readonly kits: readonly [string, string];
  readonly inputLog: ReturnType<DuelAuthority["inputLog"]>;
}

