400	 * fighters' kits in its frame-0 state.
401	 *
402	 * Visibility (§16): every client has a Colyseus StateView. After each mirror the room puts into it the client's own
403	 * ship and every ship inside that ship's sight radius, and takes out the rest, so a ship out of sight is never encoded
404	 * into that client's patches. Ships in a duel or waiting to respawn are hidden from everyone else (a duel shows as a
405	 * marker). Grapples, markers and caches are filtered by the same sight rule (a grapple's target is blanked for a
406	 * viewer who cannot see it); a player's status (gold, rubbings, what their island and dock hold, their theft choice)
407	 * and duel go to that player only, and a duel's frames and probes are messages to its two fighters. A fighter or a
408	 * player waiting to respawn sees no other ship. Terrain is static content every client already has, so it is not
409	 * synced at all.
410	 */
411	export class MatchRoom extends Room<{ state: MatchStateSchema; metadata: MatchMetadata }> {
412	  override maxClients = privateMatch.maxPlayers;
413	  /** A flood ceiling: past it Colyseus disconnects the client. Excess input is dropped well below it, in InputGate. */
414	  override maxMessagesPerSecond = MAX_INPUT_MESSAGES_PER_SECOND * 4;
415	  override patchRate = PATCH_INTERVAL_MS;
416	  override state = new MatchStateSchema();
417	
418	  private readonly config = defaultSimulationConfig;
419	  private tuning: MatchTuning = DEFAULT_MATCH_TUNING;
420	  private encounterConfig: EncounterConfig = createEncounterConfig({ map: defaultSimulationConfig.map });
421	  private simulation: MatchState = createMatchState(0);
422	  private encounters: EncounterState = createEncounterState(this.encounterConfig);
423	  private ledger: LedgerState = createMatchLedger({ map: defaultSimulationConfig.map, seed: 0, rules: objectiveRules });
424	  /** §3's ruins, one per regular island, dealt from their own seed; they alone decide opens, answers and lockouts. */
425	  private ruins: RuinsState = createMatchRuins({ islands: [], seed: () => 0 }).ruins;
426	  /** Each player's recent ruin answers by request id: a retry gets the first verdict, never a second judgement. */
427	  private readonly ruinRequests = new RuinRequests<RuinResultMessage>();
428	  /** Ruin messages per session in the current second, for the rate cap. */
429	  private readonly ruinRate = new Map<string, { windowStart: number; count: number }>();

