711	
712	  private admit(options: unknown): void {
713	    this.createToken = admitSeat(options, { code: this.state.code, createToken: this.createToken }, MATCH_ADMISSION);
714	  }
715	
716	  /** Applies a ledger step, and remembers a refusal (the room checks before it asks, so none are expected). */
717	  private ledgerStep<R extends { readonly ok: boolean; readonly rejection: string | null }>(operation: string, stepped: { state: LedgerState; result: R }): R {
718	    this.ledger = stepped.state;
719	    if (!stepped.result.ok) this.refusals.push(`${operation}: ${stepped.result.rejection}`);
720	    return stepped.result;
721	  }
722	
723	  /**
724	   * One frame of the room's clock (60 Hz). Ships sail only while the match runs (§2: player control starts after the
725	   * ready countdown and stops at the end); before and after, every helm is neutral. On every third frame the world
726	   * tick runs in §5's order (`worldTick`), and a fault inside it aborts the match (§12).
727	   */
728	  private advance(): void {
729	    if (this.paused) return;
730	    const frame = this.simulation.frame + 1;
731	    const inputs: Record<string, PlayerInput> = {};
732	    const playing = this.inPlay();
733	    const held = this.heldPlayers();
734	    for (const [sessionId, gate] of this.gates) {
735	      // No control before the start or after the end; a reserved or respawning ship ignores its player's helm (§6).
736	      if (!playing || held.has(sessionId)) inputs[sessionId] = NEUTRAL_INPUT;
737	      // A lapsed client gets no entry: its ship sails as neutral, but keeps its mooring throttle until real input.
738	      else if (!gate.lapsedAt(frame)) inputs[sessionId] = gate.inputAt(frame);
739	    }
740	    this.simulation = step(this.config, this.simulation, inputs);
741	    for (const duel of this.seaDuels.values()) duel.machine.advance();
742	    if (!isWorldStep(this.simulation.frame)) return;
743	    const tick = this.simulation.worldTick;
744	    try {
745	      this.worldTick(frame, tick, held, playing);
746	    } catch (error) {
747	      this.fault(tick, error);
748	    }
749	    for (const gate of this.gates.values()) gate.worldStepTaken();
750	    this.checkInvariants(tick);
751	    this.mirror();
752	    if (this.pauseAt !== undefined && tick >= this.pauseAt) {
753	      this.pauseAt = undefined;
754	      this.paused = true;
755	    }
756	  }
757	
758	  /**
759	   * One world tick (20 Hz), in a fixed order. While the match runs: the ledger's clock (closed theft windows settle),
760	   * the §12 timers, then §5's order: the encounters (accepted reservations first), the ledger's holds, the claim
761	   * channel, the match flow (with this tick's claim end and accomplishments), and the reveals. Before control start
762	   * only the timers and the flow run (the lobby and the ready countdown); once the match has ended nothing changes but
763	   * the settled duels' lobbies leaving their fighters' views.
764	   */
765	  private worldTick(frame: number, tick: number, held: ReadonlySet<string>, playing: boolean): void {
766	    if (this.flow.end !== null) {
767	      this.closeShownDuels(tick);
768	      return;
769	    }
770	    if (this.faultNext) {
771	      this.faultNext = false;
772	      throw new Error("test-only fault injected into the world tick");
773	    }
774	    // The ledger's clock first: choice windows that closed settle with the default theft.
775	    this.ledgerStep("advanceLedger", advanceLedger(this.ledger, { tick }));
776	    this.runAbsences(tick);
777	    let claimEnd: FlowReport | undefined;
778	    if (playing) {
779	      this.stepEncounters(frame, held);
780	      // Where everyone is now, for the ruins: casting off or entering a duel closes a session (§3).
781	      for (const ship of this.simulation.ships) this.syncRuinPresence(ship.id);
782	      // §9's eating, with this tick's reservations: a duel reserved on this tick interrupts it.
